+
+func TestDoubleStart(t *testing.T) {
+	var supervisor Supervisor
+
+	var svc1 waitservice
+	supervisor.Add(&svc1)
+
+	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
+	done := make(chan struct{})
+
+	go func() {
+		supervisor.Serve(ctx)
+		done <- struct{}{}
